import { readFile } from 'fs/promises'
import { createProject, FluentXmlFluentTest, XmlFluentXmlTest } from '../test-utils'

const SCOPE = 'x_am'

interface TestCase {
    tsFile: string
    xmlFile: string
}

interface FetchTestCase {
    xmlDir: string
    tsInput: string
    tsExpected: string
}

const testCasesDSLtoXML: TestCase[] = [
    {
        tsFile: './create/application-menu-create.now.ts',
        xmlFile: './create/xml/sys_app_application_bfa5060a92b105b6dbac9b9ccab343c4.xml',
    },
]

// TODO (jaz): verify that the expected output is actually correct.
// specifically around role/category references
const testCasesXMLtoDSL: FetchTestCase[] = [
    {
        xmlDir: './update/xml',
        tsInput: './update/application-menu-update.now.ts',
        tsExpected: './update/application-menu-update-result.now.ts',
    },
    {
        xmlDir: './update/xml-no-roles',
        tsInput: './update/application-menu-update-no-roles.now.ts',
        tsExpected: './update/application-menu-update-no-roles-result.now.ts',
    },
]

describe('Plugin: Application Menu API Test Suite', () => {
    describe('Fluent to XML', () => {
        test.each(testCasesDSLtoXML)('creates XML from %s', async ({ tsFile, xmlFile }) => {
            const project = createProject({ config: { scope: 'x_test' } })
            const file = project.addFile({
                path: `${__dirname}/create/applicationmenu.now.ts`,
                content: await readFile(`${__dirname}/${tsFile}`, 'utf8'),
            })
            project.registerExplicitId('sys_app_application', 'application-menu-id', 'application-menu-id')
            const output = await file.getOutput()
            const appMenuContent = output.find((file) => file.path.includes('sys_app_application')).content

            const expected = await readFile(`${__dirname}/${xmlFile}`, 'utf8')
            expect(appMenuContent.trim()).toEqual(expected.trim())
        })
    })

    describe('XML to Fluent', () => {
        test.each(testCasesXMLtoDSL)('creates DSL from %s', async ({ xmlDir, tsInput, tsExpected }) => {
            const project = createProject({ config: { scope: 'x_test' } })
            project.addFile(`${__dirname}/${tsInput}`)
            const result = await project.transform(`${__dirname}/${xmlDir}`)
            const content = result.changedFiles[0]?.getContent()
            const expected = await readFile(`${__dirname}/${tsExpected}`, 'utf8')
            expect(content.trim()).toEqual(expected.trim())
        })
    })

    describe('Fluent => XML => Fluent', () => {
        test('file can round-trip correctly', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const roundTripTest = new FluentXmlFluentTest(project)

            const menuId = roundTripTest.addId('sys_app_application', 'menu-id')
            const categoryId = roundTripTest.addId('sys_app_category', 'category-id')
            const roleId = roundTripTest.addCoalesceId('sys_user_role', { name: 'x_am.activity_admin' })

            roundTripTest.addExpectedXmlFileNames(
                `sys_app_application_${menuId}.xml`,
                `sys_app_category_${categoryId}.xml`,
                `sys_user_role_${roleId}.xml`
            )

            roundTripTest.addFluentFragment(
                `
import { Role, Record, ApplicationMenu } from '@servicenow/sdk/core'

Role({
    name: 'x_am.activity_admin',
    description: 'Can create, edit, publish or delete wf_element_provider',
})

const category = Record({
    table: 'sys_app_category',
    $id: Now.ID['category-id'],
    data: {
        name: 'My App Category',
        style: 'border: 1px solid #96bcdc; background-color: #FBFBFB;',
        default_order: 100,
    },
})

ApplicationMenu({
    $id: Now.ID['menu-id'],
    title: 'Some title',
    hint: 'This is a hint',
    description: 'This is a description',
    category: category,
    active: true,
    roles: ['x_am.activity_admin'],
})
`
            )

            await roundTripTest.verify()
        })
    })

    describe('XML => Fluent => XML', () => {
        test('files can round-trip correctly', async () => {
            const project = createProject({
                rootDir: __dirname,
                config: { scope: SCOPE },
            })
            const originalFiles = ['./create/xml/sys_app_application_bfa5060a92b105b6dbac9b9ccab343c4.xml']
            const roundTripTest = new XmlFluentXmlTest(project, __dirname, originalFiles)
            await roundTripTest.verify()
        })
    })
})
